import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 1000007;
    static final long MOD = 1000000007L;
    static int p, k;
    static int[] countArr = new int[MAXN];
    static int[] v = new int[MAXN];
    static int[] num = new int[MAXN];
    static List<Integer> factors = new ArrayList<>();

    static void perform_dfs(int x, int start) {
        int count = 1;
        v[x] = 1;
        while ((long)k * x % p != start) {
            x = (int)((long)k * x % p);
            v[x] = 1;
            count++;
        }
        num[count]++;
    }

    static boolean is_prime(int x) {
        if (x < 2) return false;
        for (int i = 2; i * i <= x; i++) {
            if (x % i == 0) return false;
        }
        return true;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        p = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());

        if (k == 0) {
            long result = 1;
            for (int i = 1; i < p; i++) {
                result = (result * p) % MOD;
            }
            System.out.println(result);
            return;
        }

        for (int i = 0; i < p; i++) {
            if (v[i] == 0) {
                perform_dfs(i, i);
            }
        }

        for (int i = 1; i <= p; i++) {
            if (num[i] != 0) {
                factors.add(i);
            }
        }

        long answer = 1;
        for (int i = 0; i < factors.size(); i++) {
            long temp = 0;
            int fi = factors.get(i);
            for (int j = 0; j < factors.size(); j++) {
                int fj = factors.get(j);
                if ((long)fj * fj > fi) break;
                if (fi % fj == 0) {
                    int a = fi / fj;
                    int b = fj;
                    temp += (long)a * num[a];
                    if (a != b) temp += (long)b * num[b];
                    temp %= MOD;
                }
            }
            for (int j = 0; j < num[fi]; j++) {
                answer = (answer * temp) % MOD;
            }
        }
        System.out.println(answer);
    }
}
